.yagr-tooltip {
    --yagr-tooltip-font-family:
        'Lucida Grande', 'Lucida Sans Unicode', Arial, Helvetica, sans-serif;

    position: absolute;
    z-index: 1000;
    background-color: #fff;
    border-radius: 4px;
    overflow: hidden;

    font-family: var(--yagr-tooltip-font-family);
    pointer-events: none;

    &__item {
        white-space: nowrap;
        display: flex;
        flex-direction: row;
        justify-content: left;
        align-items: center;
    }

    &__item._active {
        font-weight: bold;
    }

    &_default {
        font-size: 12px;
        padding: 4px 12px;

        box-shadow: 2px 0px 3px rgba(0, 0, 0, 0.1);

        .__title {
            font-size: 14px;
            font-weight: bold;
            margin-bottom: 4px;
        }
        .__section {
            margin-bottom: 4px;
            &:last-child {
                margin: 0;
            }
        }
        .__section_title {
            font-size: 14px;
            font-weight: bold;
            margin-bottom: 2px;
        }
        .__section_scale {
            margin-bottom: 2px;
            background-color: #eee;
            padding: 2px;
        }

        .yagr-tooltip__mark {
            width: 10px;
            height: 10px;
            border-radius: 50%;
            margin-right: 8px;
            display: block;
        }
    }

    &_pinned {
        pointer-events: all;

        ._tooltip-list {
            max-height: 320px;
        }
    }

    ._hidden-rows-number {
        white-space: nowrap;
    }

    &__idx {
        width: 25px;
        white-space: nowrap;
        max-width: 25px;
        overflow: hidden;
    }

    &__tf {
        margin-left: 4px;
.yagr {
    --yagr-font-family: 'Roboto', 'Helvetica Neue', 'Helvetica', arial, sans-serif;

    &_theme_light,
    &_theme_light-hc {
        --yagr-title-color: #333333;

        --yagr-legend-item: rgba(0, 0, 0, 0.5);
        --yagr-legend-item-hover: #000000;
        --yagr-legend-item-hidden: rgba(0, 0, 0, 0.3);

        --yagr-background: #ffffff;
        --yagr-grid: rgba(0, 0, 0, 0.105);
        --yagr-axis-stroke: rgba(0, 0, 0, 0.5);
    }

    &_theme_dark,
    &_theme_dark-hc {
        --yagr-title-color: rgba(255, 255, 255, 0.35);

        --yagr-legend-item: rgba(255, 255, 255, 0.5);
        --yagr-legend-item-hover: #a09fa3;
        --yagr-legend-item-hidden: hsla(0, 0%, 100%, 0.17);

        --yagr-background: #2d2c33;
        --yagr-grid: rgba(255, 255, 255, 0.23);
        --yagr-axis-stroke: rgba(255, 255, 255, 0.5);
    }

    &_theme_dark-hc {
        --yagr-background: rgba(34, 35, 38, 1);
    }
}

.yagr {
    width: 100%;
    height: 100%;
    font-family: var(--yagr-font-family);
    background-color: var(--yagr-background);
    // To have properly resize logic in case of using `chart.size.adaptive` property
    overflow: hidden;

    .uplot {
        width: 100%;
        font-family: var(--yagr-font-family);
    }

    .u-title {
        color: var(--yagr-title-color);
        font-size: 14px;
        font-weight: bold;
        line-height: 14px;
        margin-top: 8px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
    }

    .u-select {
        background: rgba(51, 92, 173, 0.25);
    }
}

